section.script:
      function voPickOp(v){
        try{ if(v){ localStorage.setItem('vo_op', v); } else { localStorage.removeItem('vo_op'); } }catch(e){}
        var h = window.location.search.indexOf('hist=1') !== -1 ? '&hist=1' : '';
        window.location.href = '/vue-operateur' + (v ? ('?op=' + encodeURIComponent(v) + h) : '');
      }
      (function(){
        var params = new URLSearchParams(window.location.search);
        var op = params.get('op');
        if(op){ try{ localStorage.setItem('vo_op', op); }catch(e){} }
        else {
          var s=null; try{ s=localStorage.getItem('vo_op'); }catch(e){}
          if(s){ window.location.replace('/vue-operateur?op=' + encodeURIComponent(s) + (params.get('hist')==='1' ? '&hist=1' : '')); return; }
        }
        if(params.get('hist')==='1'){
          var blocks = Array.prototype.slice.call(document.querySelectorAll('.vo-dayblock'));
          var pop=document.getElementById('vo-colis-pop'); var curOf=0; var curBtn=null;
          var lastColis=null; try{ lastColis=JSON.parse(localStorage.getItem('vo_last_colis')||'null'); }catch(e){}
          function saveLast(cid,cname){ lastColis={id:cid,name:cname}; try{ localStorage.setItem('vo_last_colis', JSON.stringify(lastColis)); }catch(e){} }
          function markDone(btn,cname){ if(!btn){ return; } var wrap=btn.parentNode; var s=document.createElement('span'); s.className='vo-pal'; s.textContent='📦 '+cname; wrap.innerHTML=''; wrap.appendChild(s); }
          function assign(ofid, cid, cname, btn, after){
            fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
              body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1971]],kwargs:{context: cid ? {active_model:'mrp.production',active_ids:[ofid],colis_id:cid} : {active_model:'mrp.production',active_ids:[ofid],colis_name:cname}}}})
            }).then(function(r){return r.json();}).then(function(d){
              if(after){ after(); }
              if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
              if(cid){ saveLast(cid,cname); }
              markDone(btn,cname);
              if(pop){ pop.style.display='none'; }
            }).catch(function(e){ if(after){ after(); } alert('Échec : '+e); });
          }
          document.querySelectorAll('.vo-addcolis').forEach(function(b){
            b.onclick=function(){ curOf=parseInt(b.getAttribute('data-ofid')); curBtn=b; if(pop){ pop.style.display='flex'; var s=document.getElementById('vo-colis-search'); if(s){ s.value=''; applySrchH(); setTimeout(function(){ s.focus(); },80); } } };
            if(lastColis && lastColis.id){
              var q=document.createElement('button'); q.type='button'; q.className='btn btn-sm btn-primary'; q.style.cssText='font-weight:800;margin-left:6px;';
              q.textContent='⚡ '+lastColis.name;
              q.onclick=function(){ q.disabled=true; assign(parseInt(b.getAttribute('data-ofid')), lastColis.id, lastColis.name, b, function(){ q.disabled=false; }); };
              b.after(q);
            }
          });
var dataC=document.getElementById('vo-colis-data');
          var COLIS=[]; try{ COLIS=JSON.parse((dataC && dataC.getAttribute('data-colis'))||'[]'); }catch(e){}
          var dynC=document.getElementById('vo-colis-dyn');
          var listC=document.getElementById('vo-colis-list');
          function rowC(c){ return '<div class="d-flex gap-1 mb-2">'
            + '<button type="button" class="vo-colis-choice btn btn-outline-primary flex-grow-1" style="font-weight:800;text-align:left;" data-cid="'+c.id+'" data-cname="'+c.name+'">'+c.name+' <span style="font-weight:600;color:#64748b;">— '+c.n+' OF</span></button>'
            + '<button type="button" class="vo-colis-lock btn btn-outline-success" style="font-weight:800;" data-cid="'+c.id+'" data-cname="'+c.name+'" title="Clôturer">🔒</button></div>'; }
          var srchC=document.getElementById('vo-colis-search');
          function applySrchH(){
            var v=(srchC && srchC.value || '').trim().toLowerCase();
            if(!v){ if(listC){ listC.style.display=''; } if(dynC){ dynC.innerHTML=''; dynC.style.display='none'; } return; }
            if(listC){ listC.style.display='none'; }
            var m=COLIS.filter(function(c){ return c.name.toLowerCase().indexOf(v)!==-1; }).slice(0,15);
            if(dynC){ dynC.style.display=''; dynC.innerHTML = m.length ? m.map(rowC).join('') : '<div class="alert alert-warning">Aucun colis ouvert ne correspond — Entrée pour chercher ce numéro exact</div>'; }
          }
          if(srchC){
            srchC.addEventListener('input', applySrchH);
            srchC.addEventListener('keydown', function(e){
              if(e.key!=='Enter'){ return; }
              e.preventDefault();
              var v=(srchC.value||'').trim(); if(!v){ return; }
              var vv=v.toLowerCase();
              var ex=COLIS.filter(function(c){ return c.name.toLowerCase()===vv; });
              if(ex.length===1){ assign(curOf, ex[0].id, ex[0].name, curBtn, null); return; }
              var m=COLIS.filter(function(c){ return c.name.toLowerCase().indexOf(vv)!==-1; });
              if(m.length===1){ assign(curOf, m[0].id, m[0].name, curBtn, null); return; }
              if(m.length>1){ return; }
              srchC.disabled=true;
              assign(curOf, null, v, curBtn, function(){ srchC.disabled=false; });
            });
          }
          var closeC=document.getElementById('vo-colis-close'); if(closeC){ closeC.onclick=function(){ pop.style.display='none'; }; }
          var zonePop=document.getElementById('vo-zone-pop'); var lockCid=0, lockName='', lockRow=null;
          if(pop){
            pop.addEventListener('click', function(e){
              var cb=e.target.closest('.vo-colis-choice');
              if(cb){ cb.disabled=true; assign(curOf, parseInt(cb.getAttribute('data-cid')), cb.getAttribute('data-cname'), curBtn, function(){ cb.disabled=false; }); return; }
              var lb=e.target.closest('.vo-colis-lock');
              if(lb){ lockCid=parseInt(lb.getAttribute('data-cid')); lockName=lb.getAttribute('data-cname'); lockRow=lb.parentNode; var n=document.getElementById('vo-zone-cname'); if(n){ n.textContent=lockName; } if(zonePop){ zonePop.style.display='flex'; } }
            });
          }
          document.querySelectorAll('.vo-zone-cancel').forEach(function(zc){ zc.onclick=function(){ zonePop.style.display='none'; }; });
          document.querySelectorAll('.vo-zone-btn').forEach(function(zb){
            zb.onclick=function(){
              zb.disabled=true;
              fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1972]],kwargs:{context:{active_model:'stock.package',active_ids:[lockCid],zone:zb.getAttribute('data-zone')}}}})
              }).then(function(r){return r.json();}).then(function(d){
                zb.disabled=false;
                if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
                zonePop.style.display='none';
                window.open('/report/pdf/maquignon.report_bon_colisage/'+lockCid, '_blank');
                if(lockRow){ lockRow.remove(); }
              }).catch(function(e){ zb.disabled=false; alert('Échec : '+e); });
            };
          });
          if(!blocks.length){ return; }
          var selHC={}, selHR={}, selHM={}, selHP={};
          function hOk(sel, card, attr){ var k=Object.keys(sel); return k.length===0 || !!sel[card.getAttribute(attr)||'']; }
          function hMatch(c){ return hOk(selHC,c,'data-client') && hOk(selHR,c,'data-ref') && hOk(selHM,c,'data-machine') && hOk(selHP,c,'data-palette'); }
          var idx = 0;
          for(var i=0;i<blocks.length;i++){ if(blocks[i].getAttribute('data-today')==='1'){ idx=i; break; } }
          var lbl=document.getElementById('vd-lbl'), prev=document.getElementById('vd-prev'), next=document.getElementById('vd-next');
          function nextVis(from,dir){ var i=from+dir; while(i>=0 && i<blocks.length){ if(blocks[i].getAttribute('data-vis')!=='0'){ return i; } i+=dir; } return -1; }
          function refreshChips(){
            var b=blocks[idx];
            var pm={}, pc={}, pr={}, pp={};
            b.querySelectorAll('.vo-card').forEach(function(card){
              pm[card.getAttribute('data-machine')||'']=1;
              pc[card.getAttribute('data-client')||'']=1;
              pr[card.getAttribute('data-ref')||'']=1;
              pp[card.getAttribute('data-palette')||'']=1;
            });
            function upd(cls, present, sel){
              document.querySelectorAll(cls).forEach(function(ch){
                var v=ch.getAttribute('data-val');
                ch.style.display = (present[v] || sel[v]) ? '' : 'none';
              });
            }
            upd('.chip-hmac',pm,selHM); upd('.chip-hcli',pc,selHC); upd('.chip-href',pr,selHR); upd('.chip-hpal',pp,selHP);
            document.querySelectorAll('.vo-hrow').forEach(function(row){
              var any=false;
              row.querySelectorAll('.vo-chip').forEach(function(ch){ if(ch.style.display!=='none'){ any=true; } });
              row.style.display = any ? '' : 'none';
            });
          }
          function show(){
            for(var i=0;i<blocks.length;i++){ blocks[i].style.display = (i===idx)?'':'none'; }
            if(lbl){ lbl.textContent = blocks[idx].getAttribute('data-label'); }
            if(next){ next.disabled = (nextVis(idx,-1)===-1); }
            if(prev){ prev.disabled = (nextVis(idx,1)===-1); }
            refreshChips();
            window.scrollTo(0,0);
          }
          function applyH(){
            var tot=0;
            for(var i=0;i<blocks.length;i++){
              var vis=0;
              blocks[i].querySelectorAll('.vo-card').forEach(function(c){ var m=hMatch(c); c.style.display=m?'':'none'; if(m){ vis++; } });
              blocks[i].setAttribute('data-vis', String(vis)); tot+=vis;
            }
            var el=document.getElementById('vo-hn'); if(el){ el.textContent=String(tot); }
            if(blocks[idx].getAttribute('data-vis')==='0'){ var j=nextVis(idx,1); if(j===-1){ j=nextVis(idx,-1); } if(j!==-1){ idx=j; } }
            show();
          }
          function chipH(sel, cls){
            document.querySelectorAll(cls).forEach(function(ch){
              ch.onclick=function(){ var v=ch.getAttribute('data-val'); if(sel[v]){ delete sel[v]; ch.classList.remove('on'); } else { sel[v]=1; ch.classList.add('on'); } applyH(); };
            });
          }
          chipH(selHM,'.chip-hmac'); chipH(selHC,'.chip-hcli'); chipH(selHR,'.chip-href'); chipH(selHP,'.chip-hpal');
          if(prev){ prev.onclick=function(){ var j=nextVis(idx,1); if(j!==-1){ idx=j; show(); } }; }
          if(next){ next.onclick=function(){ var j=nextVis(idx,-1); if(j!==-1){ idx=j; show(); } }; }
          applyH();
          return;
        }

        function bd(id,m,cls,txt){ return '<button type="button" class="vo-act btn '+cls+'" data-id="'+id+'" data-m="'+m+'">'+txt+'</button>'; }
        var popC=document.getElementById('vo-colis-pop'); var curOfP=0; var curCardP=null;
        var lastColis=null; try{ lastColis=JSON.parse(localStorage.getItem('vo_last_colis')||'null'); }catch(e){}
        function saveLastC(cid,cname){ lastColis={id:cid,name:cname}; try{ localStorage.setItem('vo_last_colis', JSON.stringify(lastColis)); }catch(e){} }
        function assignC(ofid, cid, cname, card, after){
          fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
            body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1971]],kwargs:{context: cid ? {active_model:'mrp.production',active_ids:[ofid],colis_id:cid} : {active_model:'mrp.production',active_ids:[ofid],colis_name:cname}}}})
          }).then(function(r){return r.json();}).then(function(d){
            if(after){ after(); }
            if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
            if(cid){ saveLastC(cid,cname); }
            if(popC){ popC.style.display='none'; }
            if(card){
              card.setAttribute('data-coliso', cname);
              document.querySelectorAll('.vo-card').forEach(function(c){ if(c.getAttribute('data-ofid')===card.getAttribute('data-ofid')){ c.setAttribute('data-coliso', cname); render(c); renderP(c); } });
            }
          }).catch(function(e){ if(after){ after(); } alert('Échec : '+e); });
        }
        function bindColis(root, card){
          var b=root.querySelector('.vo-addcolis2');
          if(b){ b.onclick=function(){ curOfP=parseInt(card.getAttribute('data-ofid')); curCardP=card; if(popC){ popC.style.display='flex'; var s=document.getElementById('vo-colis-search'); if(s){ s.value=''; applySrchP(); setTimeout(function(){ s.focus(); },80); } } }; }
          var q=root.querySelector('.vo-lastcolis2');
          if(q){ q.onclick=function(){ q.disabled=true; assignC(parseInt(card.getAttribute('data-ofid')), lastColis.id, lastColis.name, card, function(){ q.disabled=false; }); }; }
        }
var dataC=document.getElementById('vo-colis-data');
          var COLIS=[]; try{ COLIS=JSON.parse((dataC && dataC.getAttribute('data-colis'))||'[]'); }catch(e){}
          var dynC=document.getElementById('vo-colis-dyn');
          var listC=document.getElementById('vo-colis-list');
          function rowC(c){ return '<div class="d-flex gap-1 mb-2">'
            + '<button type="button" class="vo-colis-choice btn btn-outline-primary flex-grow-1" style="font-weight:800;text-align:left;" data-cid="'+c.id+'" data-cname="'+c.name+'">'+c.name+' <span style="font-weight:600;color:#64748b;">— '+c.n+' OF</span></button>'
            + '<button type="button" class="vo-colis-lock btn btn-outline-success" style="font-weight:800;" data-cid="'+c.id+'" data-cname="'+c.name+'" title="Clôturer">🔒</button></div>'; }
          var srchC=document.getElementById('vo-colis-search');
          function applySrchP(){
            var v=(srchC && srchC.value || '').trim().toLowerCase();
            if(!v){ if(listC){ listC.style.display=''; } if(dynC){ dynC.innerHTML=''; dynC.style.display='none'; } return; }
            if(listC){ listC.style.display='none'; }
            var m=COLIS.filter(function(c){ return c.name.toLowerCase().indexOf(v)!==-1; }).slice(0,15);
            if(dynC){ dynC.style.display=''; dynC.innerHTML = m.length ? m.map(rowC).join('') : '<div class="alert alert-warning">Aucun colis ouvert ne correspond — Entrée pour chercher ce numéro exact</div>'; }
          }
          if(srchC){
            srchC.addEventListener('input', applySrchP);
            srchC.addEventListener('keydown', function(e){
              if(e.key!=='Enter'){ return; }
              e.preventDefault();
              var v=(srchC.value||'').trim(); if(!v){ return; }
              var vv=v.toLowerCase();
              var ex=COLIS.filter(function(c){ return c.name.toLowerCase()===vv; });
              if(ex.length===1){ assignC(curOfP, ex[0].id, ex[0].name, curCardP, null); return; }
              var m=COLIS.filter(function(c){ return c.name.toLowerCase().indexOf(vv)!==-1; });
              if(m.length===1){ assignC(curOfP, m[0].id, m[0].name, curCardP, null); return; }
              if(m.length>1){ return; }
              srchC.disabled=true;
              assignC(curOfP, null, v, curCardP, function(){ srchC.disabled=false; });
            });
          }
          var closeC=document.getElementById('vo-colis-close'); if(closeC){ closeC.onclick=function(){ popC.style.display='none'; }; }
          var zonePop=document.getElementById('vo-zone-pop'); var lockCid=0, lockName='', lockRow=null;
          if(popC){
            popC.addEventListener('click', function(e){
              var cb=e.target.closest('.vo-colis-choice');
              if(cb){ cb.disabled=true; assignC(curOfP, parseInt(cb.getAttribute('data-cid')), cb.getAttribute('data-cname'), curCardP, function(){ cb.disabled=false; }); return; }
              var lb=e.target.closest('.vo-colis-lock');
              if(lb){ lockCid=parseInt(lb.getAttribute('data-cid')); lockName=lb.getAttribute('data-cname'); lockRow=lb.parentNode; var n=document.getElementById('vo-zone-cname'); if(n){ n.textContent=lockName; } if(zonePop){ zonePop.style.display='flex'; } }
            });
          }
          document.querySelectorAll('.vo-zone-cancel').forEach(function(zc){ zc.onclick=function(){ zonePop.style.display='none'; }; });
          document.querySelectorAll('.vo-zone-btn').forEach(function(zb){
            zb.onclick=function(){
              zb.disabled=true;
              fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1972]],kwargs:{context:{active_model:'stock.package',active_ids:[lockCid],zone:zb.getAttribute('data-zone')}}}})
              }).then(function(r){return r.json();}).then(function(d){
                zb.disabled=false;
                if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
                zonePop.style.display='none';
                window.open('/report/pdf/maquignon.report_bon_colisage/'+lockCid, '_blank');
                if(lockRow){ lockRow.remove(); }
              }).catch(function(e){ zb.disabled=false; alert('Échec : '+e); });
            };
          });
        function render(card){
          var st=card.getAttribute('data-state');
          var id=card.getAttribute('data-id');
          var badge=card.querySelector('.vo-badge'), acts=card.querySelector('.vo-actions');
          card.classList.toggle('doned', st==='done');
          if(st==='done'){
            badge.innerHTML='<span class="badge text-bg-secondary">✓ Terminé</span>';
            var coliso=card.getAttribute('data-coliso')||'';
            var ch='';
            if(coliso){ ch=' <span class="vo-pal">📦 '+coliso+'</span>'; }
            else {
              ch=' <button type="button" class="vo-addcolis2 btn btn-primary">📦 Mettre au colis</button>';
              if(lastColis && lastColis.id){ ch+=' <button type="button" class="vo-lastcolis2 btn btn-success" style="font-weight:800;">⚡ '+lastColis.name+'</button>'; }
            }
            acts.innerHTML=bd(id,'undo_finish','btn-outline-danger','↩ Annuler Terminé')+ch;
            bindColis(acts, card);
          }
          else if(st==='progress'){ badge.innerHTML='<span class="badge text-bg-success">▶ En cours</span>'; acts.innerHTML=bd(id,'button_pending','btn-warning','⏸ Pause')+bd(id,'button_finish','btn-success','✓ Terminer'); }
          else if(st==='blocked'){ badge.innerHTML='<span class="badge text-bg-danger">⛔ Bloquée</span>'; acts.innerHTML=''; }
          else { badge.innerHTML='<span class="badge text-bg-light">○ À faire</span>'; acts.innerHTML=bd(id,'button_start','btn-primary','▶ Démarrer'); }
          bind(acts);
        }
        function bind(root){
          root.querySelectorAll('.vo-act').forEach(function(b){
            b.onclick=function(){
              var m=b.getAttribute('data-m'), id=parseInt(b.getAttribute('data-id'));
              var card=b.closest('.vo-card');
              if(m==='button_finish' && !b.getAttribute('data-cf')){
                b.setAttribute('data-cf','1'); b.className='vo-act btn btn-danger'; b.textContent='⚠ Confirmer Terminer ?';
                setTimeout(function(){ if(b.getAttribute('data-cf')){ b.removeAttribute('data-cf'); b.className='vo-act btn btn-success'; b.textContent='✓ Terminer'; } }, 4000);
                return;
              }
              if(m==='undo_finish' && !confirm('Annuler le Terminé de cette opération ?')){ return; }
              b.disabled=true; b.textContent='…';
              var body;
              if(m==='undo_finish' || m==='button_pending'){
                var _act = (m==='undo_finish') ? 1940 : 1953;
                body = {jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[_act]],kwargs:{context:{active_model:'mrp.workorder',active_ids:[id]}}}};
              } else {
                body = {jsonrpc:'2.0',method:'call',params:{model:'mrp.workorder',method:m,args:[[id]],kwargs:{}}};
              }
              fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify(body)
              }).then(function(r){return r.json();}).then(function(d){
                if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); render(card); renderP(card); return; }
                var ns = m==='button_start' ? 'progress' : (m==='button_pending' || m==='undo_finish' ? 'ready' : 'done');
                card.setAttribute('data-state', ns); render(card); renderP(card); updateCount();
              }).catch(function(e){ alert('Échec : '+e); render(card); renderP(card); });
            };
          });
        }
        function renderP(card){
          var box=card.querySelector('.vo-pieces'); if(!box){ return; }
          var nbr=parseInt(card.getAttribute('data-nbr'))||0;
          var fait=parseInt(card.getAttribute('data-fait'))||0;
          var st=card.getAttribute('data-state');
          if(nbr <= 1 || st==='done' || st==='blocked'){ box.innerHTML=''; return; }
          var reste=Math.max(0, nbr-fait);
          box.innerHTML = '<span class="vo-fait">Fait '+fait+' / '+nbr+'</span>'
            + '<span class="vo-reste'+(reste===0?' zero':'')+'">'+(reste===0?'✅ Tout fait':'Reste '+reste)+'</span>'
            + '<button type="button" class="vo-p1 btn btn-primary"'+(reste===0?' disabled="disabled"':'')+'>+1 pièce</button>'
            + (fait>0 ? '<button type="button" class="vo-m1 btn btn-outline-secondary btn-sm">−1</button>' : '');
          function saveF(nf){
            fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
              body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'mrp.workorder',method:'write',args:[[parseInt(card.getAttribute('data-id'))],{x_studio_nbr_fait:nf}],kwargs:{}}})
            }).then(function(r){return r.json();}).then(function(d){
              if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); renderP(card); return; }
              card.setAttribute('data-fait', nf); renderP(card);
            }).catch(function(e){ alert('Échec : '+e); renderP(card); });
          }
          var p1=box.querySelector('.vo-p1'), m1=box.querySelector('.vo-m1');
          if(p1){ p1.onclick=function(){ p1.disabled=true; saveF(fait+1); }; }
          if(m1){ m1.onclick=function(){ saveF(fait-1); }; }
        }
        document.querySelectorAll('.vo-card').forEach(function(c){ render(c); renderP(c); });

        var selC={}, selR={}, selM={}, selP={}, dimQ=['','',''];
        var VOP = new URLSearchParams(location.search).get('op') || '';
        var FKEY = 'vo_filters_' + VOP;
        function saveF(){
          try{ localStorage.setItem(FKEY, JSON.stringify({c:Object.keys(selC), r:Object.keys(selR), m:Object.keys(selM), p:Object.keys(selP), d:dimQ})); }catch(e){}
        }
        function restoreF(){
          var s=null; try{ s=JSON.parse(localStorage.getItem(FKEY)||'null'); }catch(e){}
          if(!s){ return; }
          function rest(arr, sel, cls){
            var set={}; (arr||[]).forEach(function(v){ set[v]=1; });
            document.querySelectorAll(cls).forEach(function(ch){
              var v=ch.getAttribute('data-val'); if(set[v]){ sel[v]=1; ch.classList.add('on'); }
            });
          }
          rest(s.c, selC, '.chip-cli'); rest(s.r, selR, '.chip-ref'); rest(s.m, selM, '.chip-mac'); rest(s.p, selP, '.chip-pal');
          if(s.d){ dimQ=[s.d[0]||'', s.d[1]||'', s.d[2]||'']; dimIns.forEach(function(inp,i){ if(inp){ inp.value=dimQ[i]; } });
            if(dimX){ dimX.style.display=(dimQ[0]||dimQ[1]||dimQ[2])?'':'none'; } }
        }
        function apply(){
          document.querySelectorAll('.vo-card').forEach(function(c){
            var cl=c.getAttribute('data-client')||'', rf=c.getAttribute('data-ref')||'', mc=c.getAttribute('data-machine')||'', pa=c.getAttribute('data-palette')||'';
            var kc=Object.keys(selC), kr=Object.keys(selR), km=Object.keys(selM), kp=Object.keys(selP);
            var okC = kc.length===0 || selC[cl];
            var okR = kr.length===0 || selR[rf];
            var okM = km.length===0 || selM[mc];
            var okP = kp.length===0 || selP[pa];
            var okD = true;
            var cons = dimQ.map(function(v){ var f = parseFloat(v); return isNaN(f) ? null : f; })
                           .filter(function(v){ return v !== null; });
            if(cons.length){
              var pd = (c.getAttribute('data-dims')||'').split(' ').map(parseFloat)
                        .filter(function(v){ return !isNaN(v); }).sort(function(x,y){ return y-x; });
              // les axes non renseignés sont libres : on y affecte les plus grandes dimensions
              var keep = pd.slice(pd.length - Math.min(cons.length, pd.length));
              var cs = cons.slice().sort(function(x,y){ return y-x; });
              keep.sort(function(x,y){ return y-x; });
              for(var di=0; di<keep.length; di++){
                if(keep[di] > (cs[di]||0) + 0.0005){ okD = false; break; }
              }
              if(!pd.length){ okD = false; }
            }
            c.style.display = (okC && okR && okM && okP && okD) ? '' : 'none';
          });
          updateCount();
        }
        var dimIns=[document.getElementById('vo-dim-l'),document.getElementById('vo-dim-la'),document.getElementById('vo-dim-h')];
        var dimX=document.getElementById('vo-dim-x');
        dimIns.forEach(function(inp, i){
          if(!inp){ return; }
          inp.addEventListener('input', function(){
            dimQ[i] = inp.value.trim().replace(',', '.');
            if(dimX){ dimX.style.display = (dimQ[0]||dimQ[1]||dimQ[2]) ? '' : 'none'; }
            apply(); saveF();
          });
        });
        if(dimX){ dimX.onclick=function(){ dimIns.forEach(function(inp){ if(inp){ inp.value=''; } }); dimQ=['','','']; dimX.style.display='none'; apply(); saveF(); }; }
        function chip(sel, cls){
          document.querySelectorAll(cls).forEach(function(ch){
            ch.onclick=function(){
              var v=ch.getAttribute('data-val');
              if(sel[v]){ delete sel[v]; ch.classList.remove('on'); } else { sel[v]=1; ch.classList.add('on'); }
              apply(); saveF();
            };
          });
        }
        chip(selC, '.chip-cli'); chip(selR, '.chip-ref'); chip(selM, '.chip-mac'); chip(selP, '.chip-pal');
        restoreF();
        var SKEY='vo_sort_'+VOP;
        function applySort(){
          var mode='of'; try{ mode=localStorage.getItem(SKEY)||'of'; }catch(e){}
          document.querySelectorAll('.vo-sort').forEach(function(ch){ ch.classList.toggle('on', ch.getAttribute('data-sort')===mode); });
          var cards=Array.prototype.slice.call(document.querySelectorAll('.vo-card'));
          cards.sort(function(a,b){
            if(mode==='date'){
              var da=a.getAttribute('data-start')||'9999-99-99', db=b.getAttribute('data-start')||'9999-99-99';
              if(da!==db){ return da<db?-1:1; }
            }
            var oa=a.getAttribute('data-of')||'', ob=b.getAttribute('data-of')||'';
            if(oa!==ob){ return oa<ob?-1:1; }
            return (parseInt(a.getAttribute('data-id'))||0)-(parseInt(b.getAttribute('data-id'))||0);
          });
          cards.forEach(function(c){ c.parentNode.appendChild(c); });
        }
        document.querySelectorAll('.vo-sort').forEach(function(ch){
          ch.onclick=function(){ try{ localStorage.setItem(SKEY, ch.getAttribute('data-sort')); }catch(e){} applySort(); };
        });
        applySort();
        function updateCount(){
          var n=0; document.querySelectorAll('.vo-card').forEach(function(c){ if(c.style.display!=='none' && c.getAttribute('data-state')!=='done'){ n++; } });
          var el=document.getElementById('vo-count'); if(el){ el.innerHTML='<strong>'+n+'</strong> opération(s) à produire'; }
        }
        apply();
      })();
